104  
105      //M 挂上了却没开工：写明缺哪些服务。
106      if (!item.started) {
107        const names = item.missing.join('、');
108        problems.push(`插件 ${item.name} 没开工：它要用的 ${names} 没人提供`);
109      }
110    }
111    return problems;
112  }
