158  /** 从磁盘读取并校验配置，错误信息不含 YAML 原文。 */
159  function readConfig(file: string): ConfigSnapshot {
160    //M 启动和重读共用同一份入口校验。
161    const yamlText = fs.readFileSync(file, 'utf8');
162    const document = yaml.parseDocument(yamlText);
163  
164    //G YAML 解析错误会带出原文，错误里只保留行号。
165    const broken = document.errors[0];
166    if (broken !== undefined) {
167      const line = String(broken.linePos?.[0].line ?? '?');
168      throw new Error(`config.yaml 不是合法的 YAML（第 ${line} 行附近）`);
169    }
170  
171    const written: unknown = document.toJSON();
172    //M 交给 checkConfig 校验一次。顶层确认是对象后，插件仍可读取原始值。
173    const config = checks.checkConfig(written);
174    const raw = written as Record<string, unknown>;
175    return { config, raw };
176  }
177  
178  
```

### 解释
- L158–L159：`readConfig(file): ConfigSnapshot`。
- L160–L162：读文本，`yaml.parseDocument` 解析。
- L164–L169：YAML 有错 → 只报“第几行附近”，不把原文带进错误。
- L171–L175：转成对象，交给 checkConfig 校验一次；raw 留原值给插件。
- L176：函数结束；L163、L170、L177–L178 空行。

