242    /** 按 ID 更新 pi 集合。密钥变动由请求时的解析回调处理。 */
243    private updateProviders(providers: JmbotsConfig['providers'], previous: JmbotsConfig['providers']): void {
244      const created: piAi.Provider[] = [];
245      utils.eachEntry(providers, (name, provider) => {
246        const old = previous[name];
247        if (old?.baseUrl === provider.baseUrl && old.api === provider.api) return;
248  
249        //M 先建好新增或连接参数变动的供应商，再更新现有集合。
250        const getApi = CHAT_APIS[provider.api];
251        const api = getApi();
252        const auth = this.getAuth(provider, name);
253        const options = {
254          id: name, baseUrl: provider.baseUrl, auth, models: [], api,
255        };
256        const item = piAi.createProvider(options);
257        created.push(item);
258      });
259  
260      //M 移除配置里删掉的供应商，再登记准备好的新实现。
261      const configured = Object.keys(previous);
262      for (const name of configured) {
263        if (Object.hasOwn(providers, name)) continue;
264        this.models.deleteProvider(name);
265      }
266      for (const item of created) {
267        this.models.setProvider(item);
268      }
269    }
270  
```

### 解释
- L242–L243：`updateProviders(providers, previous)`；密钥变动不在这里处理，请求时由 getAuth 的回调现取。
- L244–L248：逐个看新配置；地址和协议都没变的跳过（只改密钥不用重建）。
- L249–L257：按协议取 pi 实现，配上 getAuth 的鉴权，`createProvider` 建好先放进 created。
- L260–L265：旧配置里有、新配置里没有的，`deleteProvider` 删掉。
- L266–L268：再把建好的逐个 `setProvider` 登记（同 ID 即替换）。
- L269：函数结束；L259、L270 空行。

