271    /** 监听 config.yaml，合并保存动作产生的多次文件通知。 */
272    private watchConfig(file: string): void {
273      this.ctx.effect(() => {
274        let pending: ReturnType<typeof setTimeout> | undefined;
275        //M 非持久监听与定时器让命令行模式能照常退出。
276        const watcher = fs.watch(this.root, { persistent: false }, (_event, name) => {
277          if (name !== null && name.toLowerCase() !== CONFIG_FILE) return;
278  
279          clearTimeout(pending);
280          pending = setTimeout(() => this.reloadConfig(file), CONFIG_RELOAD_DELAY_MS);
281          pending.unref();
282        });
283        watcher.on('error', (error) => {
284          console.error(`config.yaml 监听失败：${error.message}`);
285        });
286        return () => {
287          clearTimeout(pending);
288          watcher.close();
289        };
290      });
291    }
292  
```

### 解释
- L271–L273：`watchConfig(file)`，整段包在 `ctx.effect` 里，服务被拔掉时自动停。
- L274–L276：`fs.watch(this.root, { persistent: false })`：监听目录而不是文件；非持久，不挡命令行模式退出。
- L277：通知的文件名不是 config.yaml（不分大小写）就不管。
- L279–L281：清掉上一次的定时器，500 毫秒后调 reloadConfig；`unref()` 让定时器不挡进程退出。
- L283–L285：监听出错打一行，不抛。
- L286–L290：撤销函数：清定时器、关 watcher。L291 结束；L278、L292 空行。

