319     * @returns 每次请求前按供应商名从当前配置解析密钥和地址。
320     */
321    getAuth(provider: ProviderConfig, name?: string): piAi.ProviderAuth {
322      const providers = this.config.providers;
323      const providerName = name ?? Object.keys(providers).find((key) => providers[key] === provider);
324      return {
325        apiKey: {
326          name: '配置里的密钥',
327          resolve: async () => {
328            const providers = this.config.providers;
329            //G 删除供应商后，旧的鉴权回调不再交回密钥。
330            if (providerName === undefined || !Object.hasOwn(providers, providerName)) return undefined;
331  
332            //M 在同一快照取地址和密钥，缓存过模型的调用方也会向当前地址请求。
333            const current = providers[providerName]!;
334            const apiKey = current.apiKey || 'no-key';
335            return { auth: { apiKey, baseUrl: current.baseUrl }, source: CONFIG_FILE };
336          },
337        },
338      };
339    }
340  
```

### 解释
- L315–L320：文档注释：对话模型和 decision 分类器都用；provider 是配置里的对象，name 是调用方已知的供应商名。
- L321–L323：没给 name 时，按对象在当前配置里反查出供应商名。
- L324–L327：交回 `{ apiKey: { name, resolve } }`，resolve 每次请求时才调。
- L328–L330：resolve 里读**当前**配置；供应商已被删掉就交回 undefined，旧回调不再给密钥。
- L332–L335：在同一份快照里取地址和密钥（空密钥用 no-key），所以改了配置不用重建模型。
- L336–L339：闭合；L331、L340 空行。
